  const record = {
    type: "recordShopDebt",
    actorId,
    shopkeeperId: unpaid.shopkeeperId | 0,
    amount,
    reason,
    itemId,
    identity,
    name: String(spec.name ?? ctx?.query?.name?.(itemId) ?? ""),
  };

  ctx.mutate.queue(record);
